#include <bits/stdc++.h>
using namespace std;
int main(int argc,char**argv){clock_t st=clock();string base=argv[1],out=argv[2];ifstream f(base+"/degree10_source.edges");int n,m;f>>n>>m;assert(n==33397&&m==166425);vector<vector<int>>adj(n);for(int i=0,u,v;i<m;i++){f>>u>>v;adj[u].push_back(v);adj[v].push_back(u);}vector<int>pins;for(int i=0;i<n;i++)if(adj[i].size()<10){assert(adj[i].size()<=7);pins.push_back(i);}assert(pins.size()==364);int W=(n+63)/64;vector<int>seen(n),dep(n),q(n),sizes;ofstream bf(out+"/radius3.u64.bin",ios::binary);for(int i=0;i<364;i++){vector<uint64_t>b(W);int stamp=i+1,head=0,tail=1;q[0]=pins[i];seen[pins[i]]=stamp;dep[pins[i]]=0;while(head<tail){int u=q[head++];b[u>>6]|=1ULL<<(u&63);if(dep[u]==3)continue;for(int v:adj[u])if(seen[v]!=stamp){seen[v]=stamp;dep[v]=dep[u]+1;q[tail++]=v;}}bf.write((char*)b.data(),W*8);sizes.push_back(tail);}bf.close();ofstream j(out+"/radius3.json");auto vec=[&](auto&v){j<<'[';bool first=true;for(auto x:v){if(!first)j<<',';first=false;j<<x;}j<<']';};j<<"{\"n\":"<<n<<",\"m\":"<<m<<",\"pins\":";vec(pins);j<<",\"ball_sizes\":";vec(sizes);j<<",\"radius\":3,\"closed\":true,\"layout\":\"candidate-major native little-endian uint64,522words per ball\",\"bounded_radius3_balls\":364,\"allsource_BFS\":0,\"CPU_seconds\":"<<setprecision(12)<<double(clock()-st)/CLOCKS_PER_SEC<<"}\n";cerr<<"R3cpu="<<double(clock()-st)/CLOCKS_PER_SEC<<" minball="<<*min_element(sizes.begin(),sizes.end())<<" maxball="<<*max_element(sizes.begin(),sizes.end())<<'\n';}
